2	import { describe, test } from "node:test";
3	import { localArrival } from "@harbor/dispatch/eta/local";
4	import { arrivalTime, distanceKm, transitHours } from "@harbor/dispatch/eta/transit";
5	
6	describe("transit", () => {
7	  test("speed must be positive", () => {
8	    assert.throws(() => transitHours(100, 0), RangeError);
9	  });
10	
11	  test("zero distance takes no time", () => {
12	    assert.equal(transitHours(0, 14), 0);
13	  });
14	
15	  test("pilotage is added to the arrival", () => {
16	    const dep = new Date("2026-05-04T06:00:00Z");
17	    assert.equal(arrivalTime(dep, 0, 14, 2).toISOString(), "2026-05-04T08:00:00.000Z");
18	  });
19	
20	  test("distance conversion", () => {
21	    assert.ok(Math.abs(distanceKm(100) - 185.2) < 1e-9);
22	  });
23	});
24	
25	describe("local arrival", () => {
26	  test("Felixstowe in winter", () => {
27	    assert.equal(localArrival(new Date("2026-01-15T09:30:00Z"), "GBFXT"), "2026-01-15 09:30");
28	  });
29	
30	  test("unknown ports are rejected", () => {
31	    assert.throws(() => localArrival(new Date("2026-01-15T09:30:00Z"), "XXZZZ"), RangeError);
